package com.antaurora.apofirstlight.infected.breach;
import net.minecraft.world.entity.ai.goal.Goal; import net.minecraft.world.entity.monster.Zombie; import net.minecraft.world.phys.Vec3; import java.util.EnumSet;
public final class InfectedEntrySeekingGoal extends Goal { private final Zombie z; public InfectedEntrySeekingGoal(Zombie z){this.z=z;setFlags(EnumSet.of(Flag.MOVE,Flag.LOOK));}
 public boolean canUse(){InfectedBreachContext c=InfectedBreachAuthorization.getBreachContext(z);return c!=null&&InfectedEntrySeekingSystem.prepare(z,c);} public boolean canContinueToUse(){InfectedBreachContext c=InfectedBreachAuthorization.getBreachContext(z);return c!=null&&InfectedEntrySeekingSystem.isActive(z,c);}
 public void start(){moveApproach();} public void tick(){Vec3 a=InfectedEntrySeekingSystem.approach(z), i=InfectedEntrySeekingSystem.interior(z); if(a==null||i==null)return; if(z.position().distanceToSqr(a)>4&&!InfectedEntrySeekingSystem.isOpenOrGone(z)){z.getNavigation().moveTo(a.x,a.y,a.z,1.0);return;} if(InfectedEntrySeekingSystem.isOpenOrGone(z)){z.getNavigation().moveTo(i.x,i.y,i.z,1.0); if(z.position().distanceToSqr(i)<=4){InfectedEntrySeekingSystem.clear(z,"PassedEntry");}}} private void moveApproach(){Vec3 a=InfectedEntrySeekingSystem.approach(z);if(a!=null)z.getNavigation().moveTo(a.x,a.y,a.z,1.0);} }
